// ID. This ID is valid until the pen leaves proximity again (has been removed
// from the tablet's area, the tablet has been unplugged, etc). If the same
// pen reenters proximity again, it will be given a new ID.
//
// Note that "proximity" means "close enough for the tablet to know the tool
// is there." The pen touching and lifting off from the tablet while not
// leaving the area are handled by EVENT_PEN_DOWN and EVENT_PEN_UP.
//
// Not all platforms have a window associated with the pen during proximity
// events. Some wait until motion/button/etc events to offer this info.
//
// Since: SDL 3.2.0.
type PenProximityEvent struct {
	// EVENT_PEN_PROXIMITY_IN or EVENT_PEN_PROXIMITY_OUT
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The window with pen focus, if any
	WindowID WindowID
	// The pen instance id
	Which PenID
	// Complete pen input state at time of event (added in 3.4.16).
	PenState PenInputFlags
	// the device type of the pen, if known (added in 3.4.18).
	DeviceType PenDeviceType
}

// Pressure-sensitive pen touched event structure (event.ptouch.*)
//
// These events come when a pen touches a surface (a tablet, etc), or lifts
// off from one.
//
// Since: SDL 3.2.0.
type PenTouchEvent struct {
	// EVENT_PEN_DOWN or EVENT_PEN_UP
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The window with pen focus, if any
	WindowID WindowID
	// The pen instance id
	Which PenID
	// Complete pen input state at time of event
	PenState PenInputFlags
	// X coordinate, relative to window
	X float32
	// Y coordinate, relative to window
	Y float32
	// true if eraser end is used (not all pens support this).
	Eraser bool
	// true if the pen is touching or false if the pen is lifted off
	Down bool
	// the device type of the pen, if known (added in 3.4.18).
	DeviceType PenDeviceType
}

// Pinch event structure (event.pinch.*)
type PinchFingerEvent struct {
	// ::EVENT_PINCH_BEGIN or ::EVENT_PINCH_UPDATE or ::EVENT_PINCH_END
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The scale change since the last EVENT_PINCH_UPDATE. Scale < 1 is "zoom out". Scale > 1 is "zoom in".
	Scale float32
	// The window underneath the finger, if any
	WindowID WindowID
}

// The "quit requested" event
//
// Since: SDL 3.2.0.
type QuitEvent struct {
	// EVENT_QUIT
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
}

// Renderer event structure (event.render.*)
//
// Since: SDL 3.2.0.
type RenderEvent struct {
	// EVENT_RENDER_TARGETS_RESET, EVENT_RENDER_DEVICE_RESET, EVENT_RENDER_DEVICE_LOST
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The window containing the renderer in question.
	WindowID WindowID
}

// Sensor event structure (event.sensor.*)
//
// Since: SDL 3.2.0.
type SensorEvent struct {
	// EVENT_SENSOR_UPDATE
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The instance ID of the sensor
	Which SensorID
	// Up to 6 values from the sensor - additional values can be queried using GetSensorData()
	Data [6]float32
	// The timestamp of the sensor reading in nanoseconds, not necessarily synchronized with the system clock
	SensorTimestamp uint64
}

// Keyboard IME candidates event structure (event.edit_candidates.*)
//
// Since: SDL 3.2.0.
type TextEditingCandidatesEvent struct {
	// EVENT_TEXT_EDITING_CANDIDATES
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The window with keyboard focus, if any
	WindowID WindowID
	// The list of candidates, or NULL if there are no candidates available
	Candidates **byte
	// The number of strings in `candidates`
	NumCandidates int32
	// The index of the selected candidate, or -1 if no candidate is selected
	SelectedCandidate int32
	// true if the list is horizontal, false if it's vertical
	Horizontal bool
	Padding1   uint8
	Padding2   uint8
	Padding3   uint8
}

// Keyboard text editing event structure (event.edit.*)
//
// The start cursor is the position, in UTF-8 characters, where new typing
// will be inserted into the editing text. The length is the number of UTF-8
// characters that will be replaced by new typing.
//
// Since: SDL 3.2.0.
type TextEditingEvent struct {
	// EVENT_TEXT_EDITING
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The window with keyboard focus, if any
	WindowID WindowID
	// The editing text
	Text *byte
	// The start cursor of selected editing text, or -1 if not set
	Start int32
	// The length of selected editing text, or -1 if not set
	Length int32
}

// TextString returns a copy of the NUL-terminated Text string, or "" for a nil receiver
// or a NULL pointer.
//
// SDL owns the Text memory and it is valid only while the event is being handled;
// the returned string is an independent Go copy and stays valid.
func (p *TextEditingEvent) TextString() string {
	if p == nil {
		return ""
	}
	return GoString(p.Text)
}

// Keyboard text input event structure (event.text.*)
//
// This event will never be delivered unless text input is enabled by calling
// StartTextInput(). Text input is disabled by default!
//
// Since: SDL 3.2.0.
//
// See also: StartTextInput, StopTextInput
type TextInputEvent struct {
	// EVENT_TEXT_INPUT
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The window with keyboard focus, if any
	WindowID WindowID
	// The input text, UTF-8 encoded
	Text *byte
}

// TextString returns a copy of the NUL-terminated Text string, or "" for a nil receiver
// or a NULL pointer.
//
// SDL owns the Text memory and it is valid only while the event is being handled;
// the returned string is an independent Go copy and stays valid.
func (p *TextInputEvent) TextString() string {
	if p == nil {
		return ""
	}
	return GoString(p.Text)
}

// Touch finger event structure (event.tfinger.*)
//
// Coordinates in this event are normalized. `x` and `y` are normalized to a
// range between 0.0f and 1.0f, relative to the window, so (0,0) is the top
// left and (1,1) is the bottom right. Delta coordinates `dx` and `dy` are
// normalized in the ranges of -1.0f (traversed all the way from the bottom or
// right to all the way up or left) to 1.0f (traversed all the way from the
// top or left to all the way down or right).
//
// Note that while the coordinates are _normalized_, they are not _clamped_,
// which means in some circumstances you can get a value outside of this
// range. For example, a renderer using logical presentation might give a
// negative value when the touch is in the letterboxing. Some platforms might
// report a touch outside of the window, which will also be outside of the
// range.
//
// Since: SDL 3.2.0.
type TouchFingerEvent struct {
	// EVENT_FINGER_DOWN, EVENT_FINGER_UP, EVENT_FINGER_MOTION, or EVENT_FINGER_CANCELED
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The touch device id
	TouchID  TouchID
	FingerID FingerID
	// Normalized in the range 0...1
	X float32
	// Normalized in the range 0...1
	Y float32
	// Normalized in the range -1...1
	Dx float32
	// Normalized in the range -1...1
	Dy float32
	// Normalized in the range 0...1
	Pressure float32
	// The window underneath the finger, if any
	WindowID WindowID
}

// A user-defined event type (event.user.*)
//
// This event is unique; it is never created by SDL, but only by the
// application. The event can be pushed onto the event queue using
// PushEvent(). The contents of the structure members are completely up to
// the programmer; the only requirement is that ”'type”' is a value obtained
// from RegisterEvents().
//
// Since: SDL 3.2.0.
type UserEvent struct {
	// EVENT_USER through EVENT_LAST, Uint32 because these are not in the EventType enumeration
	Type     uint32
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The associated window if any
	WindowID WindowID
	// User defined event code
	Code int32
	// User defined data pointer
	Data1 unsafe.Pointer
	// User defined data pointer
	Data2 unsafe.Pointer
}

// Window state change event data (event.window.*)
//
// Since: SDL 3.2.0.
type WindowEvent struct {
	// SDL_EVENT_WINDOW_*
	Type     EventType
	Reserved uint32
	// In nanoseconds, populated using GetTicksNS()
	Timestamp uint64
	// The associated window
	WindowID WindowID
	// event dependent data
	Data1 int32
	// event dependent data
	Data2 int32
}

// A function pointer used for callbacks that watch the event queue.
//
// Parameters:
//   - userdata: what was passed as `userdata` to SetEventFilter() or AddEventWatch, etc.
//   - event: the event that triggered the callback.
//
// Returns: true to permit event to be added to the queue, and false to disallow it. When used with AddEventWatch, the return value is ignored.
//
// Thread safety: SDL may call this callback at any time from any thread; the application is responsible for locking resources the callback touches that need to be protected.
//
// Since: SDL 3.2.0.
//
// See also: SetEventFilter, AddEventWatch
//
// It holds a C function pointer; create one with NewEventFilter.
// The zero value means NULL (no callback); use NoEventFilter where an optional callback is not wanted.
type EventFilter uintptr

// NoEventFilter is the NULL EventFilter, for optional callback parameters.
const NoEventFilter EventFilter = 0

// NewEventFilter wraps fn as a C callback of type EventFilter.
//
// The callback is allocated once and never freed, and purego supports at most
// about 2000 callbacks per process: create each callback once and reuse it.
func NewEventFilter(fn func(userdata unsafe.Pointer, event *Event) bool) EventFilter {
	return EventFilter(purego.NewCallback(fn))
}

