var addrPumpEvents uintptr

func fnPumpEvents() {
	if addrPumpEvents == 0 {
		missingSymbol("SDL_PumpEvents")
	}
	call0(addrPumpEvents)
}

// Pump the event loop, gathering events from the input devices.
//
// This function updates the event queue and internal input device state.
//
// PumpEvents() gathers all the pending input information from devices and
// places it in the event queue. Without calls to PumpEvents() no events
// would ever be placed on the queue. Often the need for calls to
// PumpEvents() is hidden from the user since PollEvent() and
// WaitEvent() implicitly call PumpEvents(). However, if you are not
// polling or waiting for events (e.g. you are filtering them), then you must
// call PumpEvents() to force an event queue update.
//
// Thread safety: This function should only be called on the main thread.
//
// Since: SDL 3.2.0.
//
// See also: PollEvent, WaitEvent
func PumpEvents() {
	fnPumpEvents()
}

var addrPeepEvents uintptr

func fnPeepEvents(events *Event, numevents int32, action EventAction, minType EventType, maxType EventType) int32 {
	if addrPeepEvents == 0 {
		missingSymbol("SDL_PeepEvents")
	}
	return int32(call5(addrPeepEvents, uintptr(unsafe.Pointer(events)), uintptr(numevents), uintptr(action), uintptr(minType), uintptr(maxType)))
}

// Check the event queue for messages and optionally return them.
//
// `action` may be any of the following:
//
//   - `ADDEVENT`: up to `numevents` events will be added to the back of the
//     event queue.
//   - `PEEKEVENT`: `numevents` events at the front of the event queue,
//     within the specified minimum and maximum type, will be returned to the
//     caller and will _not_ be removed from the queue. If you pass NULL for
//     `events`, then `numevents` is ignored and the total number of matching
//     events will be returned.
//   - `GETEVENT`: up to `numevents` events at the front of the event queue,
//     within the specified minimum and maximum type, will be returned to the
//     caller and will be removed from the queue.
//
// You may have to call PumpEvents() before calling this function.
// Otherwise, the events may not be ready to be filtered when you call
// PeepEvents().
//
// Parameters:
//   - events: destination buffer for the retrieved events, may be NULL to leave the events in the queue and return the number of events that would have been stored.
//   - numevents: if action is ADDEVENT, the number of events to add back to the event queue; if action is PEEKEVENT or GETEVENT, the maximum number of events to retrieve.
//   - action: action to take; see Remarks for details.
//   - minType: minimum value of the event type to be considered; EVENT_FIRST is a safe choice.
//   - maxType: maximum value of the event type to be considered; EVENT_LAST is a safe choice.
//
// Returns: the number of events actually stored or -1 on failure; call GetError() for more information.
//
